<?php $images=query('SELECT * FROM product_images WHERE product_id=? ORDER BY position,id',[$p['id']])->fetchAll(); $rating=query("SELECT AVG(rating) rating,COUNT(*) count FROM reviews WHERE product_id=? AND status='approved'",[$p['id']])->fetch(); ?>
<section class="section product-detail" itemscope itemtype="https://schema.org/Product"><nav class="breadcrumb" aria-label="Breadcrumb" itemscope itemtype="https://schema.org/BreadcrumbList"><a href="/">Home</a> / <a href="/<?=e($p['type'])?>"><?=e(ucfirst($p['type']))?></a> / <span><?=e($p['name'])?></span></nav><div class="detail-grid"><div class="gallery"><button class="gallery-main" aria-label="Zoom product image" data-zoom><img id="main-product-image" itemprop="image" src="<?=e($images[0]['path']??'/assets/images/placeholder.svg')?>" alt="<?=e($p['name'])?>" width="800" height="1000"></button><div class="thumbnails"><?php foreach($images as $im): ?><button data-gallery="<?=e($im['path'])?>" aria-label="<?=e($im['alt'])?>"><img src="<?=e($im['path'])?>" alt="<?=e($im['alt'])?>" width="120" height="150"></button><?php endforeach ?></div><p class="muted">Select a thumbnail · Click the image to zoom</p></div><div class="product-info"><p class="eyebrow"><?=e($p['category_name'])?> / THE WIKI EDIT</p><h1 itemprop="name"><?=e(str_replace('WIKI ','',$p['name']))?></h1><p class="rating"><?=$rating['count']?'★ '.number_format((float)$rating['rating'],1).' · '.(int)$rating['count'].' reviews':'Be the first to review this piece'?></p><div itemprop="offers" itemscope itemtype="https://schema.org/Offer"><meta itemprop="priceCurrency" content="<?=e(cfg('currency'))?>"><meta itemprop="price" content="<?=e(($p['sale_price']??$p['price'])/100)?>"><link itemprop="availability" href="https://schema.org/<?=array_sum(array_column($variants,'stock'))>0?'InStock':'OutOfStock'?>"><p class="detail-price"><span id="variant-price"><?=money((int)($p['sale_price']??$p['price']))?></span><?php if($p['sale_price']!==null): ?> <del><?=money($p['price'])?></del> <span class="badge"><?=round((1-$p['sale_price']/$p['price'])*100)?>% off</span><?php endif ?></p></div><p itemprop="description"><?=e($p['short_description'])?></p><form method="post" action="/api/action" data-ajax id="product-form" data-base-price="<?=e($p['sale_price']??$p['price'])?>"><?=csrf_field()?><input type="hidden" name="action" value="cart"><input type="hidden" name="mode" value="add"><label for="variant">Choose <?= $p['type']==='clothing'?'size & color':'your volume'?></label><select id="variant" name="variant_id" required><option value="">Select an option</option><?php foreach($variants as $v): ?><option value="<?=e($v['id'])?>" data-stock="<?=e($v['stock'])?>" data-adjustment="<?=e($v['price_adjustment'])?>" <?=$v['stock']<1?'disabled':''?>><?=e(trim($v['size'].' '.$v['color'].' '.$v['volume']))?> · <?=$v['stock']>0?'In stock':'Sold out'?></option><?php endforeach ?></select><div class="stock-note" id="variant-stock">Select an option to see availability.</div><div class="quantity-row"><label>Quantity<input type="number" name="quantity" min="1" max="20" value="1" required></label><a href="/size-guide" class="underlined"><?= $p['type']==='clothing'?'Size & fit guide':'Find your scent'?> ↗</a></div><button class="btn full" id="add-to-cart" disabled>Add to bag <span>↗</span></button><button class="btn secondary full" id="buy-now" data-buy-now disabled>Buy now</button></form><form method="post" action="/api/action" data-ajax><?=csrf_field()?><input type="hidden" name="action" value="wishlist"><input type="hidden" name="product_id" value="<?=e($p['id'])?>"><button class="text-button">♡ Save to wishlist</button></form><div class="delivery-note">↗ Complimentary delivery over PKR 15,000<br>↶ Easy returns within 14 days. <a href="/refund-policy">Conditions apply</a>.</div><p class="muted">SKU: <span itemprop="sku"><?=e($p['sku'])?></span> · <span itemprop="brand">WIKI</span></p><details open><summary>The details</summary><p><?=nl2br(e($p['description']))?></p></details><details><summary>Specifications & care</summary><?php if($p['type']==='scents'): ?><dl><?php foreach(['fragrance_family','top_notes','middle_notes','base_notes','gender','longevity','concentration'] as $k): ?><dt><?=e(ucwords(str_replace('_',' ',$k)))?></dt><dd><?=e($p[$k])?></dd><?php endforeach ?></dl><?php else: ?><p>Cold gentle wash. Wash with similar colors. Dry naturally in shade. Refer to your garment label for composition and care.</p><?php endif ?></details></div></div>
<section class="review-section"><h2>Customer reviews</h2><?php $reviews=query("SELECT r.*,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.product_id=? AND r.status='approved' ORDER BY r.id DESC LIMIT 30",[$p['id']])->fetchAll(); if(!$reviews): ?><p>No reviews yet. Your experience could help someone find their favorite.</p><?php endif ?><?php foreach($reviews as $r): ?><blockquote><span><?=str_repeat('★',$r['rating'])?></span><p><?=e($r['body'])?></p><cite><?=e($r['name'])?> · <?=$r['verified']?'Verified purchase':''?></cite></blockquote><?php endforeach ?><?php if(user()): ?><form class="form-panel" method="post" action="/api/action" data-ajax><?=csrf_field()?><input type="hidden" name="action" value="review"><input type="hidden" name="product_id" value="<?=e($p['id'])?>"><h3>Share your experience</h3><p>Available for delivered purchases. Reviews are moderated.</p><label>Rating<select name="rating"><?php foreach([5,4,3,2,1] as $n): ?><option value="<?=$n?>"><?=$n?> stars</option><?php endforeach ?></select></label><label>Your review<textarea name="body" maxlength="3000" required></textarea></label><button class="btn">Submit review</button></form><?php else: ?><a class="underlined" href="/login">Sign in to write a review ↗</a><?php endif ?></section><div class="section-heading"><h2>You might also love.</h2><a class="underlined" href="/shop">Explore more ↗</a></div><div class="product-grid"><?php $related=Catalog::products(['type'=>$p['type']],5); $shown=0; foreach($related as $item) if($item['id']!==$p['id'] && $shown++<4) require ROOT.'/views/partials/card.php'; ?></div><?php if($recent): ?><h2 class="spaced">Recently viewed</h2><div class="recent-links"><?php foreach(array_slice($recent,0,4) as $slug): ?><a class="btn secondary" href="/product/<?=e($slug)?>"><?=e(ucwords(str_replace('-',' ',$slug)))?></a><?php endforeach ?></div><?php endif ?></section><dialog id="zoom-dialog"><button type="button" class="icon" data-close-zoom aria-label="Close image zoom">×</button><img alt="Enlarged product view" id="zoom-image" src="<?=e($images[0]['path']??'/assets/images/placeholder.svg')?>"></dialog>
